// The Outer News icon on the site (#65, 28 Oct): Yurii's N with the red news
// block, on white (docs/design/icon/outer-news-icon.jpg), as PNGs made from it
// (docs/design/icon). Kept in the Worker, so a page view loads nothing from
// elsewhere (LyFi lesson 2): the tab icon rides inline in every page as a
// data: URL (about 9 KB), and the two bigger ones have a URL of their own,
// fetched once and kept a day (respond.ts, CACHE.icon).

/** The tab icon: the red N with "NEWS", without its little O, on a clear background (Yurii, 29 Oct, Roman's logo), 128 px so it stays sharp on Retina tabs, as a data: URL, so the browser asks for no /favicon.ico. */
export const TAB_ICON = "data:image/png;base64,";

const bytes = (base64: string): Uint8Array => Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));

/** /apple-touch-icon.png: 180 px, what Safari puts on a home screen. */
export const APPLE_TOUCH_ICON = bytes("");

/** /icon-512.png: the picture a link preview shows (og:image), 512 px. */
export const OG_IMAGE = bytes("");
